/* shared SLA view: slippages, outliers and exceptions, grouped by state and District Sales Manager */
(function(){var ST=window.ST,BA=ST&&ST.BA,FV=window.FV;if(!ST||!FV)return;var esc=BA.esc,KL={ack:'Engineer did not accept in 18 h',nosch:'No visit date set',visit:'Site visit late',assign:'Not assigned in 4 h',review:'Checker review late',report:'Report late'};
FV.slaPanel=function(o){o=o||{};var all=FV.breaches().filter(function(b){return !o.state||b.state===o.state}),hard=all.filter(function(b){return !b.soft}),t2=hard.filter(function(b){return b.tier>=2}),t1=hard.filter(function(b){return b.tier===1}),
 dsms=FV.dsms(o.state),rows=dsms.map(function(m){var mine=hard.filter(function(b){return b.dsm===m.id}),ords=FV.orders().filter(function(x){return x.dsm===m.id}),sent=ords.filter(function(x){return x.st==='sent'}),ot=sent.filter(function(x){return x.sentAt<=x.due}).length,cm=FV.get(m.manager);return {m:m,cm:cm,n:mine.length,e:mine.filter(function(b){return b.tier>=2}).length,rep:sent.length?Math.round(ot/sent.length*100)+'% ('+ot+'/'+sent.length+')':'—'}}).sort(function(a,b){return b.e-a.e||b.n-a.n}),
 ex=BA.jget('ba3_rptx',[]);
 return ST.panel('SLA slippages and exceptions',
 '<div class="kpis" style="margin-bottom:14px">'+ST.kpi('Open slippages',hard.length,'Past the promised time')+ST.kpi('With circle manager',t1.length,'6 hours or more late')+ST.kpi('Needs leadership',t2.length,'24 hours or more late')+ST.kpi('Reports due soon',all.filter(function(b){return b.soft}).length,'Within 24 hours of the 72 h promise')+'</div>'+
 '<h3 style="font:800 15px var(--f);margin:6px 0 8px">Outliers needing action ('+t2.length+')</h3>'+ST.table(['Property','Owner','District Sales Manager','What slipped','Late by','State'],t2.map(function(b){var d=FV.get(b.dsm);return '<tr><td><b>'+esc(b.prop)+'</b><br><small style="color:var(--mute)">'+b.pid+'</small></td><td>'+esc(b.owner)+'<br><small style="color:var(--mute)">'+esc(b.role)+'</small></td><td>'+(d?esc(d.name):'—')+'</td><td>'+esc(b.text)+'</td><td><b style="color:#A50E0E">'+FV.left(b.over)+'</b></td><td>'+esc(b.state||'')+'</td></tr>'}))+(t2.length?'':'<p style="color:var(--mute);margin:8px 0 0">No outliers. Every slippage is still being handled by a District Sales Manager or Circle Manager.</p>')+
 '<h3 style="font:800 15px var(--f);margin:20px 0 8px">District Sales Managers: scorecard</h3>'+ST.table(['District Sales Manager','Districts','Circle Manager','Open slippages','Past 24 h','Reports on time'],rows.map(function(r){return '<tr><td><b>'+esc(r.m.name)+'</b><br><small style="color:var(--mute)">'+esc(r.m.state)+'</small></td><td>'+esc((r.m.districts||[]).join(', '))+'</td><td>'+(r.cm?esc(r.cm.name):'—')+'</td><td>'+(r.n?'<b style="color:#8A5A00">'+r.n+'</b>':0)+'</td><td>'+(r.e?'<b style="color:#A50E0E">'+r.e+'</b>':0)+'</td><td>'+r.rep+'</td></tr>'}))+
 '<h3 style="font:800 15px var(--f);margin:20px 0 8px">Exceptions raised by circle managers ('+ex.filter(function(x){return !o.state||x.state===o.state}).length+')</h3>'+ST.table(['When','Report','Raised by','Concern'],ex.filter(function(x){return !o.state||x.state===o.state}).slice().reverse().map(function(x){return '<tr><td>'+ST.ago(x.at)+'</td><td>'+esc(x.order)+'<br><small style="color:var(--mute)">'+esc(x.prop)+'</small></td><td>'+esc(x.by)+'</td><td>'+esc(x.why)+'</td></tr>'}))+(ex.length?'':'<p style="color:var(--mute);margin:8px 0 0">No exception raised yet.</p>'),'')};
})();
